def patch_source(data, expected, edits):
    normalized = data.replace(b"\r\n", b"\n")
    if blob_hash(normalized) != expected:
        raise ValueError("Unexpected source revision.")
    text = normalized.decode("utf-8")
    for before, after in edits:
        if text.count(before) != 1:
            raise ValueError("Source anchor differs.")
        text = text.replace(before, after)
    updated = text.encode("utf-8")
    return updated.replace(b"\n", b"\r\n") if b"\r\n" in data else updated

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    root = args.checkout.resolve()
    try:
        if not (root / ".git").exists():
            raise ValueError("Use a separate Git checkout.")
        pending = {}
        for path, expected, edits in SPECS:
            target = root / path
            if target.resolve() != target or not target.is_file():
                raise ValueError("Invalid source path.")
            data = target.read_bytes()
            if path == QUERY_SOURCE:
                original = subprocess.check_output(["git", "show", "HEAD:" + path], cwd=root)
                predecessor = query_patch(original)
                if data.replace(b"\r\n", b"\n") != predecessor.replace(b"\r\n", b"\n"):
                    raise ValueError("Unexpected query-patched builder predecessor.")
                # The pinned original is verified by query_patch. Preserve its
                # exact predecessor edits and check all builder anchors.
                pending[target] = patch_source(data, blob_hash(predecessor.replace(b"\r\n", b"\n")), edits)
            else:
                pending[target] = patch_source(data, expected, edits)
        if args.apply:
            for target, data in pending.items():
                target.write_bytes(data)
            print("Builder and budget candidate applied.")
        else:
            print("Sources validated; dry run only.")
    except (OSError, ValueError, subprocess.CalledProcessError) as exc:
        print(exc, file=sys.stderr)
        return 1
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
